\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/6/32/\",\"title\":\"TEXT 32\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1952,\"bb\":568133,\"url_path\":\"/en/library/bg/6/31/devanagari/\",\"body_final\":\"सर्वभूतस्थितं यो मां भजत्येकत्वमास्थित: ।
सर्वथा वर्तमानोऽपि स योगी मयि वर्तते ॥ ३१ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1953,\"bb\":1726,\"url_path\":\"/en/library/bg/6/31/b1726/\",\"body_value\":\"sarva-bhūta-sthitaṁ yo māṁ
bhajaty ekatvam āsthitaḥ
sarvathā vartamāno ’pi
sa yogī mayi vartate\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1954,\"bb\":1727,\"url_path\":\"/en/library/bg/6/31/b1727/\",\"shadow_value\":\"sarva-bhūta-sthitam – situated in everyone’s heart; yaḥ – he who; mām – Me; bhajati – serves in devotional service; ekatvam – in oneness; āsthitaḥ – situated; sarvathā – in all respects; vartamānaḥ – being situated; api – in spite of; saḥ – he; yogī – the transcendentalist; mayi – in Me; vartate – remains.\",\"word_for_word_value\":[{\"word\":\"sarva-bhūta-sthitam\",\"translation\":\"situated in everyone’s heart\"},{\"word\":\"yaḥ\",\"translation\":\"he who\"},{\"word\":\"mām\",\"translation\":\"Me\"},{\"word\":\"bhajati\",\"translation\":\"serves in devotional service\"},{\"word\":\"ekatvam\",\"translation\":\"in oneness\"},{\"word\":\"āsthitaḥ\",\"translation\":\"situated\"},{\"word\":\"sarvathā\",\"translation\":\"in all respects\"},{\"word\":\"vartamānaḥ\",\"translation\":\"being situated\"},{\"word\":\"api\",\"translation\":\"in spite of\"},{\"word\":\"saḥ\",\"translation\":\"he\"},{\"word\":\"yogī\",\"translation\":\"the transcendentalist\"},{\"word\":\"mayi\",\"translation\":\"in Me\"},{\"word\":\"vartate\",\"translation\":\"remains\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1955,\"bb\":1728,\"url_path\":\"/en/library/bg/6/31/b1728/\",\"body_value\":\"Such a yogī, who engages in the worshipful service of the Supersoul, knowing that I and the Supersoul are one, remains always in Me in all circumstances.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1956,\"bb\":1729,\"url_path\":\"/en/library/bg/6/31/b1729/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1957,\"bb\":1730,\"url_path\":\"/en/library/bg/6/31/b1730/\",\"body_value\":\"dik-kālādy-anavacchinne
kṛṣṇe ceto vidhāya ca
tan-mayo bhavati kṣipraṁ
jīvo brahmaṇi yojayet\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1958,\"bb\":1731,\"url_path\":\"/en/library/bg/6/31/b1731/\",\"body_value\":\"“By concentrating one’s attention on the transcendental form of Kṛṣṇa, who is all-pervading and beyond time and space, one becomes absorbed in thinking of Kṛṣṇa and then attains the happy state of transcendental association with Him.”\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1959,\"bb\":1732,\"url_path\":\"/en/library/bg/6/31/b1732/\",\"body_value\":\"Kṛṣṇa consciousness is the highest stage of trance in yoga practice. This very understanding that Kṛṣṇa is present as Paramātmā in everyone’s heart makes the yogī faultless. The Vedas (Gopāla-tāpanī Upaniṣad 1.21) confirm this inconceivable potency of the Lord as follows: eko ’pi san bahudhā yo ’vabhāti. “Although the Lord is one, He is present in innumerable hearts as many.” Similarly, in the smṛti-śāstra it is said:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1960,\"bb\":1733,\"url_path\":\"/en/library/bg/6/31/b1733/\",\"body_value\":\"eka eva paro viṣṇuḥ
sarva-vyāpī na saṁśayaḥ
aiśvaryād rūpam ekaṁ ca
